1	import { MagneticCornerTracker } from "../components/Button.js";
2	import { BlockOverlay } from "./BlockOverlay.js";
3	import { TextReveal } from "../animation/TextReveal.js";
4	import { DOM_CONFIG, MASKING, STATE_CLASSES } from "../config/dom.config.js";
5	import {
6	  MASKING_ANIM,
7	  DRAWER_ANIM,
8	  DRAWER_CLASSES,
9	  DRAWER_GNB_RECT,
10	} from "../config/component.config.js";
11	import { UI } from "../ui/UI.js";
12	import { Aria } from "../utils/Aria.js";
13	import type { DrawerConfig } from "../types/dom.types.js";
14	import type { MagneticCornerGsap } from "../types/component.types.js";
15	import type {
16	  GsapGlobal,
17	  GsapTweenLike,
18	  WindowWithGsap,
19	} from "../types/gsap.types.js";
20	import type { ITimelineActionTarget } from "../types/engine.types.js";
21	import { drawer } from "../core/setup.js";
22	
23	const activeTweens = new WeakMap<
24	  HTMLElement,
25	  { open?: GsapTweenLike; close?: GsapTweenLike }
26	>();
27	function getGsap(): GsapGlobal | undefined {
28	  return (window as WindowWithGsap).gsap;
29	}
