31	export class Drawer extends UI implements ITimelineActionTarget {
32	  private static _lockReleases = new WeakMap<HTMLElement, () => void>();
33	  declare config: DrawerConfig;
34	
35	  private _triggerSelector: string | undefined;
36	  private _revealGroups: string[] | undefined;
37	  private _triggerEl: HTMLButtonElement | null = null;
38	  private _magneticCorner: MagneticCornerTracker | null = null;
39	  private _gnbRectCleanups: Array<() => void> = [];
40	  private _boundFlipVisibility: () => void;
41	  private _boundKeydown: (e: KeyboardEvent) => void;
42	
43	  static getInstance(options: Partial<DrawerConfig> = {}): Drawer {
44	    const selector = options.selector ?? DOM_CONFIG.drawer.selector;
45	    return UI.getOrCreate(Drawer, { ...options, selector });
46	  }
47	
48	  constructor(config: DrawerConfig = { selector: DOM_CONFIG.drawer.selector }) {
49	    const selector = config.selector ?? DOM_CONFIG.drawer.selector;
50	    super({ ...config, selector });
51	    this._triggerSelector = config.triggerSelector;
52	    this._revealGroups = config.revealGroups ?? DOM_CONFIG.drawer.revealGroups;
53	    this._boundFlipVisibility = this._flipVisibility.bind(this);
54	    this._boundKeydown = this._onKeydown.bind(this);
55	    this.updateOptions(config);
56	  }
57	
58	  override updateOptions(config: Partial<DrawerConfig>): void {
59	    super.updateOptions(config);
60	    if (config.triggerSelector !== undefined) {
61	      this._triggerSelector = config.triggerSelector;
62	    }
63	    if (config.revealGroups !== undefined) {
64	      this._revealGroups = config.revealGroups;
65	    } else {
66	      this._revealGroups = DOM_CONFIG.drawer.revealGroups;
67	    }
68	  }
69	
70	  protected override applyVisibility(visible: boolean): void {
71	    if (visible) {
72	      this._show();
73	      return;
74	    }
75	    this._hide();
76	  }
77	
78	  readonly timelineKey = drawer;
79	
80	  getTimelineCallback(vars: Record<string, unknown>): (() => void) | null {
81	    if (typeof vars.visible === "boolean") {
82	      return vars.visible
83	        ? () => this.setVisibleOn()
84	        : () => this.setVisibleOff();
85	    }
86	    if (vars.show) return () => this.setVisibleOn();
87	    if (vars.hide) return () => this.setVisibleOff();
88	    return null;
89	  }
90	
91	  override init(): void {
92	    super.init();
93	  }
94	
95	  protected mount(): void {
96	    if (this.isDisposed) return;
97	    const root = this.getElement();
98	    if (!root) return;
99	
100	    this._mountTrigger(root);
101	    document.addEventListener("keydown", this._boundKeydown);
102	    this._mountMagneticCorner(root);
103	    this._initGnbRects(root);
104	  }
105	
106	  private _mountTrigger(root: HTMLElement): void {
107	    if (!this._triggerSelector) return;
108	    const trigger = document.querySelector<HTMLButtonElement>(
109	      this._triggerSelector,
110	    );
111	    if (!trigger) return;
112	    this._triggerEl = trigger;
113	    trigger.addEventListener("click", this._boundFlipVisibility);
114	    this._syncAria(root.classList.contains("is-open"));
115	  }
116	
117	  private _mountMagneticCorner(root: HTMLElement): void {
118	    const gsap = getGsap();
119	    if (!gsap || typeof gsap.killTweensOf !== "function") return;
120	    this._magneticCorner = MagneticCornerTracker.createForDrawer(
121	      root,
122	      gsap as MagneticCornerGsap,
123	    );
124	  }
125	
126	  private _initGnbRects(root: HTMLElement): void {
127	    const gsap = getGsap();
128	    if (!gsap) return;
129	
130	    const links = Array.from(
131	      root.querySelectorAll<HTMLElement>(DOM_CONFIG.drawer.gnbLinkSelector),
132	    );
133	
134	    for (const link of links) {
135	      const rectEl = link.querySelector<HTMLElement>(DRAWER_GNB_RECT.rectSelector);
136	      const labelEl = link.querySelector<HTMLElement>(DRAWER_GNB_RECT.labelSelector);
137	      if (!rectEl || !labelEl) continue;
138	
139	      gsap.set(rectEl, {
140	        opacity: DRAWER_GNB_RECT.initOpacity,
141	        scale: DRAWER_GNB_RECT.initScale,
142	        transformOrigin: DRAWER_GNB_RECT.transformOrigin,
143	        yPercent: -50,
144	      });
145	      gsap.set(labelEl, { x: 0 });
146	
147	      if (link.classList.contains(DRAWER_CLASSES.linkActive)) {
148	        const w = rectEl.getBoundingClientRect().width;
149	        const gap = this._readLinkGap(link);
150	        gsap.set(rectEl, { opacity: 1, scale: 1 });
151	        gsap.set(labelEl, { x: w + gap });
152	      }
153	
154	      const onEnter = (): void => {
155	        const g = getGsap();
156	        if (!g) return;
157	        const w = rectEl.getBoundingClientRect().width;
158	        const gap = this._readLinkGap(link);
159	        g.to(rectEl, { opacity: 1, scale: 1, duration: DRAWER_GNB_RECT.enterDuration, ease: DRAWER_GNB_RECT.enterEase, overwrite: "auto" });
160	        g.to(labelEl, { x: w + gap, duration: DRAWER_GNB_RECT.enterDuration, ease: DRAWER_GNB_RECT.enterEase, overwrite: "auto" });
161	      };
162	
163	      const onLeave = (): void => {
164	        if (link.classList.contains(DRAWER_CLASSES.linkActive)) return;
165	        const g = getGsap();
166	        if (!g) return;
167	        g.to(rectEl, { opacity: DRAWER_GNB_RECT.initOpacity, scale: DRAWER_GNB_RECT.initScale, duration: DRAWER_GNB_RECT.leaveDuration, ease: DRAWER_GNB_RECT.leaveEase, overwrite: "auto" });
168	        g.to(labelEl, { x: 0, duration: DRAWER_GNB_RECT.leaveDuration, ease: DRAWER_GNB_RECT.leaveEase, overwrite: "auto" });
169	      };
170	
171	      link.addEventListener("mouseenter", onEnter);
172	      link.addEventListener("mouseleave", onLeave);
173	
174	      this._gnbRectCleanups.push((): void => {
175	        link.removeEventListener("mouseenter", onEnter);
176	        link.removeEventListener("mouseleave", onLeave);
177	        const g = getGsap();
178	        if (g) {
179	          g.killTweensOf?.([rectEl, labelEl]);
180	          g.set(labelEl, { x: 0 });
181	          g.set(rectEl, { opacity: 0, scale: DRAWER_GNB_RECT.initScale, yPercent: -50 });
182	        }
183	      });
184	    }
185	  }
186	
187	  private _readLinkGap(link: HTMLElement): number {
188	    const raw = window.getComputedStyle(link).columnGap;
189	    const parsed = parseFloat(raw);
190	    return Number.isFinite(parsed) ? parsed : 0;
191	  }
192	
193	  private _syncAria(isVisible: boolean): void {
194	    Aria.setExpanded(this._triggerEl, isVisible);
195	    Aria.setControls(this._triggerEl, this.element?.id ?? "drawer-panel");
196	    Aria.setHidden(this.element ?? null, !isVisible);
197	  }
198	
199	  private _onKeydown(e: KeyboardEvent): void {
200	    if (e.key !== "Escape") return;
201	    if (!this.element?.classList.contains("is-open")) return;
202	    this.setVisibleOff();
203	  }
204	
205	  private _show(): void {
206	    if (!this.element) return;
207	    this.element.classList.add("is-open");
208	    this._syncAria(true);
209	    this._visible = true;
210	  }
211	
212	  private _hide(): void {
213	    if (!this.element) return;
214	    this.element.classList.remove("is-open");
215	    this._syncAria(false);
216	    this._visible = false;
217	  }
218	
219	  private _flipVisibility(): void {
220	    if (!this.element) return;
221	    const isVisible = this.element.classList.toggle("is-open");
222	    this._syncAria(isVisible);
223	    this._visible = isVisible;
224	  }
225	
226	  override getVisibleState(): boolean {
227	    return this.element?.classList.contains("is-open") ?? false;
228	  }
229	
230	  override animateIn(): void {
231	    if (!this.element || !this._triggerEl) return;
232	    Drawer.runOpenTransition(
233	      this.element,
234	      this._triggerEl,
235	      "is-open",
236	      this._revealGroups,
237	    );
238	  }
239	
240	  override animateOut(): void {
241	    if (!this.element || !this._triggerEl) return;
242	    const header = document.querySelector<HTMLElement>("#main-header");
243	    Drawer.runCloseTransition(
244	      this.element,
245	      this._triggerEl,
246	      header,
247	      "is-open",
248	      () => undefined,
249	    );
250	  }
251	
252	  static runOpenTransition(
253	    drawer: HTMLElement,
254	    _trigger: HTMLButtonElement,
255	    _openClass: string,
256	    revealGroups?: string[],
257	    onTransitionDone?: () => void,
258	  ): void {
259	    const inner = drawer.querySelector<HTMLElement>(
260	      DOM_CONFIG.drawer.innerSelector,
261	    );
262	    const bag = activeTweens.get(drawer) ?? {};
263	    bag.open?.kill?.();
264	    bag.close?.kill?.();
265	    activeTweens.set(drawer, bag);
266	
267	    drawer.style.opacity = "";
268	    drawer.classList.remove(DRAWER_CLASSES.textRevealReady);
269	    drawer.classList.add(STATE_CLASSES.animatingIn);
270	
271	    (async () => {
272	      await BlockOverlay.playIn();
273	      drawer.classList.remove(STATE_CLASSES.animatingIn);
274	      drawer.style.opacity = "1";
275	      if (inner) {
276	        inner.style.opacity = "1";
277	        inner.style.transform = "translateY(0)";
278	      }
279	      await BlockOverlay.playOut();
280	      drawer.classList.add(DRAWER_CLASSES.textRevealReady);
281	      setTimeout(
282	        () =>
283	          Drawer.revealMaskingInOrder(
284	            drawer,
285	            revealGroups ?? DOM_CONFIG.drawer.revealGroups,
286	          ),
287	        DRAWER_ANIM.openMaskingDelayMs,
288	      );
289	    })()
290	      .catch(() => {
291	      })
292	      .finally(() => {
293	        onTransitionDone?.();
294	      });
295	  }
296	
297	  static runCloseTransition(
298	    drawer: HTMLElement,
299	    trigger: HTMLButtonElement,
300	    header: HTMLElement | null,
301	    openClass: string,
302	    onComplete: () => void,
303	    onTransitionDone?: () => void,
304	  ): void {
305	    const bag = activeTweens.get(drawer) ?? {};
306	    bag.open?.kill?.();
307	    bag.close?.kill?.();
308	    drawer.style.opacity = "";
309	    activeTweens.set(drawer, bag);
310	
311	    drawer.classList.remove(DRAWER_CLASSES.textRevealReady);
312	    TextReveal.setVisibleOff(drawer);
313	
314	    (async () => {
315	      await new Promise<void>((r) =>
316	        window.setTimeout(r, MASKING_ANIM.textOutMs),
317	      );
318	
319	      await BlockOverlay.playIn();
320	
321	      if (drawer.contains(document.activeElement)) trigger.focus();
322	      drawer.classList.remove(openClass);
323	      trigger.classList.remove(openClass);
324	      header?.classList.remove(openClass);
325	      Aria.setExpanded(trigger, false);
326	      Aria.setHidden(drawer, true);
327	      Aria.setExpanded(header ?? null, false);
328	      Drawer.releaseLock(drawer);
329	      onComplete();
330	
331	      await BlockOverlay.playOut();
332	    })()
333	      .catch(() => {
334	      })
335	      .finally(() => {
336	        onTransitionDone?.();
337	      });
338	  }
339	
340	  private static revealMaskingInOrder(
341	    drawer: HTMLElement,
342	    groups: string[],
343	  ): void {
344	    let delay = 0;
345	
346	    for (const groupSel of groups) {
347	      const items = Array.from(
348	        drawer.querySelectorAll<HTMLElement>(`${groupSel} ${MASKING.selector}`),
349	      );
350	      items.forEach((el) => {
351	        setTimeout(() => TextReveal.setVisibleOn(el), delay);
352	        delay += MASKING_ANIM.staggerMs;
353	      });
354	      delay += MASKING_ANIM.groupGapMs;
355	    }
356	  }
357	
358	  static runTextOutOnly(
359	    drawerPanel: HTMLElement,
360	    _trigger: HTMLButtonElement,
361	    _header: HTMLElement | null,
362	    _openClass: string,
363	  ): Promise<void> {
364	    TextReveal.setVisibleOff(drawerPanel);
365	    drawerPanel.classList.add(STATE_CLASSES.barbaLeaving);
366	    return new Promise<void>((resolve) => {
367	      window.setTimeout(() => resolve(), MASKING_ANIM.textOutMs);
368	    });
369	  }
370	
371	  static runTextOutThenClose(
372	    drawerPanel: HTMLElement,
373	    trigger: HTMLButtonElement,
374	    header: HTMLElement | null,
375	    openClass: string,
376	  ): Promise<void> {
377	    TextReveal.setVisibleOff(drawerPanel);
378	    drawerPanel.classList.add(STATE_CLASSES.barbaLeaving);
379	
380	    return new Promise<void>((resolve) => {
381	      window.setTimeout(() => {
382	        drawerPanel.classList.remove(STATE_CLASSES.barbaLeaving);
383	        if (
384	          document.activeElement &&
385	          drawerPanel.contains(document.activeElement)
386	        ) {
387	          trigger.focus();
388	        }
389	        drawerPanel.classList.remove(openClass);
390	        Aria.setHidden(drawerPanel, true);
391	        Drawer.releaseLock(drawerPanel);
392	        trigger.classList.remove(openClass);
393	        Aria.setExpanded(trigger, false);
394	        header?.classList.remove(openClass);
395	        Aria.setExpanded(header ?? null, false);
396	        const h = trigger.closest("header");
397	        if (h?.classList.contains(openClass)) {
398	          h.classList.remove(openClass);
399	          Aria.setExpanded(h, false);
400	        }
401	        resolve();
402	      }, MASKING_ANIM.textOutMs);
403	    });
404	  }
405	
406	  static syncNavActiveState(): void {
407	    const currentPath = window.location.pathname || "/";
408	
409	    const setActive = (link: HTMLAnchorElement): void => {
410	      const href = link.getAttribute("href");
411	      if (href == null) return;
412	      const hrefPath = href.startsWith("http") ? new URL(href).pathname : href;
413	      const isActive =
414	        hrefPath === "/"
415	          ? currentPath === "/" || currentPath === ""
416	          : currentPath === hrefPath ||
417	            currentPath.startsWith(hrefPath.replace(/\/$/, "") + "/");
418	      link.classList.toggle(DRAWER_CLASSES.linkActive, isActive);
419	    };
420	
421	    document
422	      .querySelectorAll<HTMLAnchorElement>(DOM_CONFIG.drawer.gnbLinkSelector)
423	      .forEach((el) => setActive(el));
424	    document
425	      .querySelectorAll<HTMLAnchorElement>(DOM_CONFIG.drawer.gnbSubLinkSelector)
426	      .forEach((el) => setActive(el));
427	  }
428	
429	  static attachLock(drawer: HTMLElement, release: () => void): void {
430	    const prev = Drawer._lockReleases.get(drawer);
431	    if (prev) prev();
432	    Drawer._lockReleases.set(drawer, release);
433	  }
434	
435	  static releaseLock(drawer: HTMLElement): void {
436	    const release = Drawer._lockReleases.get(drawer);
437	    if (!release) return;
438	    Drawer._lockReleases.delete(drawer);
439	    release();
440	  }
441	
442	  override dispose(): void {
443	    this._magneticCorner?.destroy();
444	    this._magneticCorner = null;
445	    if (this._triggerEl) {
446	      this._triggerEl.removeEventListener("click", this._boundFlipVisibility);
447	      this._triggerEl = null;
448	    }
449	    document.removeEventListener("keydown", this._boundKeydown);
450	    for (const cleanup of this._gnbRectCleanups) cleanup();
451	    this._gnbRectCleanups = [];
452	
453	    super.dispose();
454	  }
455	}
