1	import { UI } from "../ui/UI.js";
2	import { Aria } from "../utils/Aria.js";
3	import { ScrollLock } from "../utils/ScrollLock.js";
4	import { DOM_CONFIG } from "../config/dom.config.js";
5	import { Drawer } from "./Drawer.js";
6	import { Panel } from "./Panel.js";
7	import type { HeaderMenuToggleOptions } from "../types/component.types.js";
8	
9	export class Header extends UI {
10	  private _triggerSelector = "[data-drawer-trigger]";
11	  private _headerSelector = DOM_CONFIG.keys.header;
12	  private _openClass = "is-open";
13	  private _boundFlagAttr = "headerToggleBound";
14	  private _trigger: HTMLButtonElement | null = null;
15	  private _header: HTMLElement | null = null;
16	  private _transitioning = false;
17	  private _queuedVisible: boolean | null = null;
18	  /** 드로어를 연 시점의 Panel 표시 여부 — 닫을 때 원래 숨김이었으면 복구 */
19	  private _panelVisibleBeforeDrawer: boolean | null = null;
20	
21	  private _scrolledClass = "visual";
22	  private _scrollListener: (() => void) | null = null;
23	
24	  private readonly _onTriggerClick = (): void => this._flip();
25	  private readonly _onDocumentKeydown = (event: KeyboardEvent): void =>
26	    this._onEscape(event);
27	  private readonly _onDocumentClick = (event: MouseEvent): void =>
28	    this._onOutside(event);
29	
30	  constructor(options: HeaderMenuToggleOptions = {}) {
31	    super({ selector: options.drawerSelector ?? DOM_CONFIG.drawer.selector });
32	    this.setOption(options);
33	  }
34	
35	  setOption(options: HeaderMenuToggleOptions = {}): void {
36	    if (options.drawerSelector) this.config.selector = options.drawerSelector;
37	    if (options.triggerSelector)
38	      this._triggerSelector = options.triggerSelector;
39	    if (options.headerSelector) this._headerSelector = options.headerSelector;
40	    if (options.openClass) this._openClass = options.openClass;
41	    if (options.boundFlagAttr) this._boundFlagAttr = options.boundFlagAttr;
42	  }
43	
44	  protected override mount(): void {
45	    const drawer = this.getElement();
46	    if (!drawer) return;
47	    const trigger = document.querySelector<HTMLButtonElement>(
48	      this._triggerSelector,
49	    );
50	    if (!trigger) return;
51	    if (trigger.dataset[this._boundFlagAttr] === "true") return;
52	    trigger.dataset[this._boundFlagAttr] = "true";
53	    this._trigger = trigger;
54	    this._header = document.querySelector<HTMLElement>(this._headerSelector);
55	    this._visible = drawer.classList.contains(this._openClass);
56	    this._syncAria(this._visible);
57	    trigger.addEventListener("click", this._onTriggerClick);
58	    document.addEventListener("keydown", this._onDocumentKeydown);
59	    document.addEventListener("click", this._onDocumentClick);
60	    this._scrollListener = () => this._syncScrollState();
61	    window.addEventListener("scroll", this._scrollListener, { passive: true });
62	    this._syncScrollState();
63	  }
64	
65	  protected override applyVisibility(visible: boolean): void {
66	    if (this._transitioning) {
67	      this._queuedVisible = visible;
68	      return;
69	    }
70	    this._transitioning = true;
71	    if (visible) {
72	      this._show();
73	      return;
74	    }
75	    this._hide();
76	  }
77	
78	  override getVisibleState(): boolean {
79	    return this.getElement()?.classList.contains(this._openClass) ?? false;
80	  }
81	
82	  private _show(): void {
83	    const drawer = this.getElement();
84	    const trigger = this._trigger;
85	    if (!drawer || !trigger) {
86	      this._done();
87	      return;
88	    }
89	    drawer.classList.add(this._openClass);
90	    trigger.classList.add(this._openClass);
91	    this._header?.classList.add(this._openClass);
92	    this._syncAria(true);
93	    Drawer.attachLock(drawer, ScrollLock.lock());
94	    const panel = Panel.getInstance();
95	    panel.init();
96	    this._panelVisibleBeforeDrawer = panel.getVisibleState();
97	    if (this._panelVisibleBeforeDrawer) {
98	      panel.setVisibleOff();
99	    }
100	    Drawer.runOpenTransition(drawer, trigger, this._openClass, undefined, () =>
101	      this._done(),
102	    );
103	  }
104	
105	  private _hide(): void {
106	    const drawer = this.getElement();
107	    const trigger = this._trigger;
108	    if (!drawer || !trigger) {
109	      this._restorePanelAfterDrawerClose();
110	      this._done();
111	      return;
112	    }
113	    Drawer.runCloseTransition(
114	      drawer,
115	      trigger,
116	      this._header,
117	      this._openClass,
118	      () => undefined,
119	      () => {
120	        this._restorePanelAfterDrawerClose();
121	        this._done();
122	      },
123	    );
124	  }
125	
126	  private _flip(): void {
127	    this._setVisibility(!this.getVisibleState());
128	  }
129	
130	  private _syncScrollState(): void {
131	    this._header?.classList.toggle(this._scrolledClass, window.scrollY > 0);
132	  }
133	
134	  private _onEscape(event: KeyboardEvent): void {
135	    if (event.key !== "Escape") return;
136	    if (!this.getVisibleState()) return;
137	    this.setVisibleOff();
138	    this._trigger?.focus();
139	  }
140	
141	  private _onOutside(event: MouseEvent): void {
142	    if (!this.getVisibleState()) return;
143	    const drawer = this.getElement();
144	    const trigger = this._trigger;
145	    const target = event.target;
146	    if (!(target instanceof Node) || !drawer || !trigger) return;
147	    if (drawer.contains(target) || trigger.contains(target)) return;
148	    this.setVisibleOff();
149	  }
150	
151	  private _syncAria(isVisible: boolean): void {
152	    Aria.setExpanded(this._trigger, isVisible);
153	    Aria.setControls(this._trigger, this.getElement()?.id ?? "drawer-panel");
154	    Aria.setHidden(this.getElement(), !isVisible);
155	    Aria.setExpanded(this._header, isVisible);
156	  }
157	
158	  private _restorePanelAfterDrawerClose(): void {
159	    const wasVisible = this._panelVisibleBeforeDrawer;
160	    this._panelVisibleBeforeDrawer = null;
161	    if (wasVisible === true) {
162	      Panel.getInstance().setVisibleOn();
163	    }
164	  }
