166	  private _done(): void {
167	    this._transitioning = false;
168	    const queuedVisible = this._queuedVisible;
169	    this._queuedVisible = null;
170	    if (typeof queuedVisible !== "boolean") return;
171	    if (queuedVisible === this.getVisibleState()) return;
172	    this._setVisibility(queuedVisible);
173	  }
