175	  override dispose(): void {
176	    this._trigger?.removeEventListener("click", this._onTriggerClick);
177	    document.removeEventListener("keydown", this._onDocumentKeydown);
178	    document.removeEventListener("click", this._onDocumentClick);
179	    if (this._scrollListener) {
180	      window.removeEventListener("scroll", this._scrollListener);
181	      this._scrollListener = null;
182	    }
