178	  static buildTexture(
179	    proj: WorkProjectItem,
180	    size: WorkCardSize,
181	    image?: HTMLImageElement | null,
182	    renderOptions: WorkCardRenderOptions = WORK_CARD_DEFAULT_RENDER_OPTIONS,
