148	    host.replaceChildren(modal);
149	    void modal.offsetWidth;
150	    modal.classList.add("is-open");
151	    this._activeModal = modal;
152	    this._visible = true;
153	    this._releaseScrollLock?.();
154	    this._releaseScrollLock = ScrollLock.lock({ pauseLenis: false });
155	    this._bindModalEvents(modal);
156	  }
157	
158	  private _bindModalEvents(modal: HTMLElement): void {
159	    this._activeAbortController?.abort();
160	    const abortController = new AbortController();
161	    this._activeAbortController = abortController;
162	    const closeNodes = Array.from(
163	      modal.querySelectorAll<HTMLElement>(this._closeSelector),
164	    );
165	    closeNodes.forEach((node) =>
166	      node.addEventListener("click", () => this._hide(), {
167	        signal: abortController.signal,
168	      }),
169	    );
170	    document.addEventListener(
171	      "keydown",
172	      (event) => {
173	        if (event.key === "Escape") this._hide();
174	      },
175	      { signal: abortController.signal },
176	    );
177	  }
178	
179	  private _hide(immediate = false): void {
180	    if (!this._activeModal) return;
181	    this._requestAbortController?.abort();
182	    this._requestAbortController = null;
183	    this._activeAbortController?.abort();
184	    this._activeAbortController = null;
185	    if (this._closeTimer !== null) {
186	      window.clearTimeout(this._closeTimer);
187	      this._closeTimer = null;
188	    }
189	    const closingModal = this._activeModal;
190	    const reduceMotion =
191	      ResponsiveRuntime.getDefault().getSnapshot().flags.reducedMotion;
192	    const closeMs = immediate || reduceMotion ? 0 : 320;
193	    closingModal.classList.remove("is-open");
194	    closingModal.classList.add("is-closing");
195	    const finalize = (): void => {
196	      this._ensureHost().replaceChildren();
197	      this._activeModal = null;
198	      this._visible = false;
199	      this._releaseScrollLock?.();
200	      this._releaseScrollLock = null;
201	    };
202	    if (closeMs === 0) {
203	      finalize();
204	      return;
205	    }
206	    this._closeTimer = window.setTimeout(() => {
207	      finalize();
208	      this._closeTimer = null;
209	    }, closeMs);
210	  }
211	
212	  private _ensureHost(): HTMLElement {
213	    const existing = document.getElementById(this._hostId);
214	    if (existing) {
215	      this.setElement(existing);
216	      return existing;
217	    }
218	    const host = document.createElement("div");
219	    host.id = this._hostId;
220	    Aria.setLive(host, "polite");
221	    document.body.appendChild(host);
222	    this.setElement(host);
223	    return host;
224	  }
225	
226	  override dispose(): void {
227	    this._hide(true);
228	    this._triggerAbortController?.abort();
229	    this._triggerAbortController = null;
230	    this._requestAbortController?.abort();
231	    this._requestAbortController = null;
232	    this._activeAbortController?.abort();
233	    this._activeAbortController = null;
234	    if (this._closeTimer !== null) {
235	      window.clearTimeout(this._closeTimer);
236	      this._closeTimer = null;
237	    }
238	    this._openDebounce.offCancel();
239	    this._activeModal = null;
240	    this._openLock = false;
241	    this._pendingEndpoint = null;
242	    this._releaseScrollLock?.();
243	    this._releaseScrollLock = null;
244	    super.dispose();
245	  }
246	}
