6	export class Dropdown extends UI {
7	  private _openClass = "is-open";
8	  private _trigger: HTMLButtonElement | null = null;
9	  private _panel: HTMLElement | null = null;
10	  private _label: HTMLElement | null = null;
11	  private _input: HTMLInputElement | null = null;
12	  private _options: HTMLElement[] = [];
13	  private _selectedIndex = 0;
14	  private _bindings: Array<{
15	    option: HTMLElement;
16	    onClick: () => void;
17	    onKeydown: (event: KeyboardEvent) => void;
18	  }> = [];
19	
20	  private readonly _onTriggerClick = (): void => {
21	    console.log("[Dropdown] trigger click", this.getElement()?.id ?? "unknown");
22	    this._flip();
23	  };
24	  private readonly _onTriggerKeydown = (event: KeyboardEvent): void =>
25	    this._onTriggerKey(event);
26	  private readonly _onDocumentClick = (event: MouseEvent): void =>
27	    this._onOutside(event);
28	
29	  constructor(
30	    root: HTMLElement,
31	    options: { openClass?: string } = {},
32	  ) {
33	    super({ selector: "#dropdown-item" } as ComponentConfig);
34	    this.setElement(root);
35	    if (options.openClass) this._openClass = options.openClass;
36	  }
37	
38	  protected override mount(): void {
39	    const root = this.getElement();
40	    if (!root) return;
41	    this._trigger = root.querySelector<HTMLButtonElement>(".no-dropdown__trigger");
42	    this._panel = root.querySelector<HTMLElement>(".no-dropdown__panel");
43	    this._label = root.querySelector<HTMLElement>(".no-dropdown__trigger-label");
44	    this._input = root.querySelector<HTMLInputElement>("[data-dropdown-input]");
45	    this._options = Array.from(root.querySelectorAll<HTMLElement>(".no-dropdown__item"));
46	    if (!this._trigger || !this._panel || !this._label || this._options.length === 0) {
47	      return;
48	    }
49	    this._selectedIndex = this._resolveSelectedIndex();
50	    this._select(this._selectedIndex);
51	    this.setVisibleOff();
52	
53	    this._trigger.addEventListener("click", this._onTriggerClick);
54	    this._trigger.addEventListener("keydown", this._onTriggerKeydown);
55	    this._options.forEach((option, index) => {
56	      const onClick = (): void => this._onOptionClick(index);
57	      const onKeydown = (event: KeyboardEvent): void =>
58	        this._onOptionKey(event, index);
59	      option.addEventListener("click", onClick);
60	      option.addEventListener("keydown", onKeydown);
61	      this._bindings.push({ option, onClick, onKeydown });
62	    });
63	    document.addEventListener("click", this._onDocumentClick);
64	  }
65	
66	  protected override applyVisibility(visible: boolean): void {
67	    const root = this.getElement();
68	    if (!root || !this._trigger || !this._panel) return;
69	    root.classList.toggle(this._openClass, visible);
70	    this._syncAria(visible);
71	  }
72	
73	  isDetached(): boolean {
74	    return !this.getElement()?.isConnected;
75	  }
76	
77	  private _flip(): void {
78	    this._setVisibility(!this.getVisibleState());
79	  }
80	
81	  private _syncAria(isVisible: boolean): void {
82	    Aria.setExpanded(this._trigger, isVisible);
83	    Aria.setControls(this._trigger, this._panel?.id ?? "dropdown-panel");
84	    Aria.setHidden(this._panel, !isVisible);
85	  }
86	
87	  private _select(index: number): void {
88	    if (index < 0 || index >= this._options.length || !this._label) return;
89	    this._selectedIndex = index;
90	    this._options.forEach((option, optionIndex) => {
91	      const selected = optionIndex === index;
92	      option.classList.toggle("is-selected", selected);
93	      Aria.setSelected(option, selected);
94	      option.tabIndex = selected ? 0 : -1;
95	    });
96	    const selected = this._options[index];
97	    if (!selected) return;
98	    this._label.textContent = selected.textContent ?? "";
99	    if (!this._input) return;
100	    const value = selected.dataset.value ?? "";
101	    if (this._input.value === value) return;
102	    this._input.value = value;
103	    dispatchInputChange(this._input);
104	  }
105	
106	  private _onTriggerKey(event: KeyboardEvent): void {
107	    if (event.key !== "ArrowDown" && event.key !== "ArrowUp" && event.key !== "Escape") {
108	      return;
109	    }
110	    if (event.key === "Escape") {
111	      this.setVisibleOff();
112	      return;
113	    }
114	    event.preventDefault();
115	    this.setVisibleOn();
116	    this._selectedIndex = this._moveIndex(
117	      this._selectedIndex,
118	      event.key === "ArrowDown" ? 1 : -1,
119	    );
120	    this._select(this._selectedIndex);
121	    this._options[this._selectedIndex]?.focus();
122	  }
123	
124	  private _onOptionClick(index: number): void {
125	    console.log("[Dropdown] option click", {
126	      rootId: this.getElement()?.id ?? "unknown",
127	      index,
128	      value: this._options[index]?.dataset.value ?? "",
129	    });
130	    this._select(index);
131	    this.setVisibleOff();
132	    this._trigger?.focus();
133	  }
134	
135	  private _onOptionKey(event: KeyboardEvent, index: number): void {
136	    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
137	      event.preventDefault();
138	      this._selectedIndex = this._moveIndex(
139	        this._selectedIndex,
140	        event.key === "ArrowDown" ? 1 : -1,
141	      );
142	      this._select(this._selectedIndex);
143	      this._options[this._selectedIndex]?.focus();
144	      return;
145	    }
146	    if (event.key === "Enter" || event.key === " ") {
147	      event.preventDefault();
148	      this._onOptionClick(index);
149	      return;
150	    }
151	    if (event.key === "Escape") {
152	      event.preventDefault();
153	      this.setVisibleOff();
154	      this._trigger?.focus();
155	    }
156	  }
157	
158	  private _onOutside(event: MouseEvent): void {
159	    if (!this.getVisibleState()) return;
160	    const target = event.target;
161	    const root = this.getElement();
162	    if (!(target instanceof Node) || !root) return;
163	    if (root.contains(target)) return;
164	    this.setVisibleOff();
165	  }
166	
167	  private _resolveSelectedIndex(): number {
168	    const ariaIndex = this._options.findIndex(
169	      (option) => Aria.isSelected(option),
170	    );
171	    if (ariaIndex >= 0) return ariaIndex;
172	    const classIndex = this._options.findIndex((option) =>
173	      option.classList.contains("is-selected"),
174	    );
175	    if (classIndex >= 0) return classIndex;
176	    return 0;
177	  }
178	
179	  private _moveIndex(current: number, delta: number): number {
180	    const size = this._options.length;
181	    if (size <= 0) return 0;
182	    const next = current + delta;
183	    if (next < 0) return size - 1;
184	    if (next >= size) return 0;
185	    return next;
186	  }
187	
188	  override dispose(): void {
189	    this._trigger?.removeEventListener("click", this._onTriggerClick);
190	    this._trigger?.removeEventListener("keydown", this._onTriggerKeydown);
191	    document.removeEventListener("click", this._onDocumentClick);
192	    this._bindings.forEach(({ option, onClick, onKeydown }) => {
193	      option.removeEventListener("click", onClick);
194	      option.removeEventListener("keydown", onKeydown);
195	    });
196	    this._bindings = [];
197	    this._options = [];
198	    this._trigger = null;
199	    this._panel = null;
200	    this._label = null;
201	    this._input = null;
202	    super.dispose();
203	  }
204	}
