1	import { UI_PANEL, UI_PANEL_AUTOPLAY } from "../config/component.config.js";
2	import type { ComponentConfig } from "../types/dom.types.js";
3	import { Helpers } from "../utils/Helpers.js";
4	import { UI } from "./UI.js";
5	
6	export class Panel extends UI {
7	  private _progressRoot: HTMLElement | null = null;
8	  private _progressSegments: HTMLElement[] = [];
9	  private _rulerTicks: HTMLElement[] = [];
10	  private _progressTimerId: number | null = null;
11	  private _rulerFrameId: number | null = null;
12	  private _rulerStartedAt = 0;
13	  private _progressStep = 0;
14	
15	  static getInstance(options: Partial<ComponentConfig> = {}): Panel {
16	    const selector = options.selector ?? UI_PANEL.selector;
17	    return UI.getOrCreate(Panel, { ...options, selector }) as Panel;
18	  }
19	
20	  constructor(config: ComponentConfig = { selector: UI_PANEL.selector }) {
21	    const selector = config.selector ?? UI_PANEL.selector;
22	    super({ ...config, selector });
23	  }
24	
25	  protected override mount(): void {
26	    if (!this.element) return;
27	    this._collectElements();
28	    this.element.classList.toggle(UI_PANEL.visibleClass, this._visible);
29	    this._syncAutoplay(this._visible);
30	  }
31	
32	  protected override applyVisibility(visible: boolean): void {
33	    this.element?.classList.toggle(UI_PANEL.visibleClass, visible);
34	    this._syncAutoplay(visible);
35	  }
36	
37	  override dispose(): void {
38	    this._stopAutoplay();
39	    this._progressRoot = null;
40	    this._progressSegments = [];
41	    this._rulerTicks = [];
42	    super.dispose();
43	  }
44	
45	  private _collectElements(): void {
46	    if (!this.element) return;
47	    this._progressRoot = this.element.querySelector<HTMLElement>(
48	      UI_PANEL_AUTOPLAY.progressSelector,
49	    );
50	    this._progressSegments = Array.from(
51	      this.element.querySelectorAll<HTMLElement>(
52	        UI_PANEL_AUTOPLAY.progressSegmentSelector,
53	      ),
54	    );
55	    this._rulerTicks = Array.from(
56	      this.element.querySelectorAll<HTMLElement>(
57	        UI_PANEL_AUTOPLAY.rulerTickSelector,
58	      ),
59	    ).sort((left, right) => {
60	      const leftValue = Number(left.dataset.value ?? 0);
61	      const rightValue = Number(right.dataset.value ?? 0);
62	      return leftValue - rightValue;
63	    });
64	    this._progressStep = 0;
65	    this._applyProgressFrame(0);
66	    this._applyRulerFrame(0);
67	  }
68	
69	  private _syncAutoplay(visible: boolean): void {
70	    if (!visible) {
71	      this._stopAutoplay();
72	      return;
73	    }
74	    this._startAutoplay();
75	  }
76	
77	  private _startAutoplay(): void {
78	    if (this._progressSegments.length > 0 && this._progressTimerId == null) {
79	      this._applyProgressFrame(this._progressStep);
80	      this._progressTimerId = window.setInterval(() => {
81	        this._progressStep =
82	          (this._progressStep + 1) % (this._progressSegments.length + 1);
83	        this._applyProgressFrame(this._progressStep);
84	      }, UI_PANEL_AUTOPLAY.progressIntervalMs);
85	    }
86	
87	    if (this._rulerTicks.length === 0 || this._rulerFrameId != null) return;
88	    this._rulerStartedAt = performance.now();
89	    this._tickRuler();
90	  }
91	
92	  private _stopAutoplay(): void {
93	    if (this._progressTimerId != null) {
94	      window.clearInterval(this._progressTimerId);
95	      this._progressTimerId = null;
96	    }
97	    if (this._rulerFrameId != null) {
98	      window.cancelAnimationFrame(this._rulerFrameId);
99	      this._rulerFrameId = null;
100	    }
101	  }
102	
103	  private _applyProgressFrame(activeCount: number): void {
104	    if (this._progressRoot) {
105	      this._progressRoot.setAttribute(
106	        "aria-valuenow",
107	        String(Math.min(activeCount, this._progressSegments.length)),
108	      );
109	    }
110	
111	    this._progressSegments.forEach((segment, index) => {
112	      segment.classList.toggle("is-filled", index < activeCount);
113	    });
114	  }
115	
116	  private _tickRuler(): void {
117	    const tickCount = this._rulerTicks.length;
118	    if (tickCount === 0) {
119	      this._rulerFrameId = null;
120	      return;
121	    }
122	    const duration = Math.max(UI_PANEL_AUTOPLAY.rulerDurationMs, 1);
123	    const elapsed = (performance.now() - this._rulerStartedAt) % duration;
124	    const progress = elapsed / duration;
125	    this._applyRulerFrame(progress * tickCount);
126	    this._rulerFrameId = window.requestAnimationFrame(() => {
127	      this._tickRuler();
128	    });
129	  }
130	
131	  private _applyRulerFrame(activeProgress: number): void {
132	    this._rulerTicks.forEach((tick, index) => {
133	      const strength = Helpers.clamp01(activeProgress - index);
134	      tick.style.setProperty("--ruler-strength", strength.toFixed(4));
135	      tick.classList.toggle(UI_PANEL_AUTOPLAY.activeClass, strength >= 0.98);
136	    });
137	  }
138	}
