2	import {
3	  BLOCK_OVERLAY,
4	  BLOCK_OVERLAY_ANIM,
5	  BLOCK_OVERLAY_STYLE,
6	} from "../config/component.config.js";
7	import { FrameScheduler } from "../utils/FrameScheduler.js";
8	import { Aria } from "../utils/Aria.js";
9	import type { DomStyleEntries } from "../types/runtime.types.js";
10	import { ResponsiveRuntime } from "../runtime/ResponsiveRuntime.js";
11	
12	export class BlockOverlay {
13	  private static _overlayEl: HTMLElement | null = null;
14	
15	  private static _applyStyleEntries(
16	    element: HTMLElement,
17	    entries: DomStyleEntries,
18	  ): void {
19	    entries.forEach(([property, value]) => {
20	      element.style.setProperty(property, value);
21	    });
22	  }
23	
24	  private static _applyOverlayGridStyles(overlay: HTMLElement): void {
25	    BlockOverlay._applyStyleEntries(overlay, BLOCK_OVERLAY_STYLE.overlay);
26	    overlay.style.gridTemplateRows = `repeat(${BLOCK_OVERLAY_ANIM.rows}, 1fr)`;
27	    overlay.style.gridTemplateColumns = "1fr";
28	  }
29	
30	  private static _applyBlockBaseStyles(block: HTMLElement): void {
31	    BlockOverlay._applyStyleEntries(block, BLOCK_OVERLAY_STYLE.block);
32	  }
33	
34	  private static getOverlay(): HTMLElement {
35	    if (BlockOverlay._overlayEl?.isConnected) return BlockOverlay._overlayEl;
36	    const existing = document.querySelector<HTMLElement>(`.${BLOCK_OVERLAY.overlayClass}`);
37	    if (existing) {
38	      BlockOverlay._overlayEl = existing;
39	      BlockOverlay.ensureBlockCount(existing);
40	      BlockOverlay.applyStyles(existing);
41	      return existing;
42	    }
43	    const el = document.createElement("div");
44	    el.className = BLOCK_OVERLAY.overlayClass;
45	    Aria.setHidden(el, true);
46	    BlockOverlay._applyOverlayGridStyles(el);
47	    for (let i = 0; i < BLOCK_OVERLAY_ANIM.rows; i++) {
48	      const b = document.createElement("div");
49	      b.className = BLOCK_OVERLAY.blockClass;
50	      BlockOverlay._applyBlockBaseStyles(b);
51	      el.appendChild(b);
52	    }
53	    document.body.appendChild(el);
54	    BlockOverlay._overlayEl = el;
55	    return el;
56	  }
57	
58	  private static ensureBlockCount(overlay: HTMLElement): void {
59	    let list = overlay.querySelectorAll(`.${BLOCK_OVERLAY.blockClass}`);
60	    while (list.length > BLOCK_OVERLAY_ANIM.rows) {
61	      list[list.length - 1].remove();
62	      list = overlay.querySelectorAll(`.${BLOCK_OVERLAY.blockClass}`);
63	    }
64	    while (list.length < BLOCK_OVERLAY_ANIM.rows) {
65	      const b = document.createElement("div");
66	      b.className = BLOCK_OVERLAY.blockClass;
67	      BlockOverlay._applyBlockBaseStyles(b);
68	      overlay.appendChild(b);
69	      list = overlay.querySelectorAll(`.${BLOCK_OVERLAY.blockClass}`);
70	    }
71	  }
72	
73	  private static applyStyles(overlay: HTMLElement): void {
74	    BlockOverlay._applyOverlayGridStyles(overlay);
75	    overlay.querySelectorAll<HTMLElement>(`.${BLOCK_OVERLAY.blockClass}`).forEach((el) => {
76	      BlockOverlay._applyBlockBaseStyles(el);
77	    });
78	  }
79	
80	  private static setBlocksTransform(
81	    overlay: HTMLElement,
82	    transform: string,
83	    origin: "left" | "right",
84	  ): void {
85	    overlay.querySelectorAll<HTMLElement>(`.${BLOCK_OVERLAY.blockClass}`).forEach((el) => {
86	      el.style.transformOrigin = origin;
87	      el.style.transform = transform;
88	    });
89	  }
90	
91	  private static setBlocksTransition(overlay: HTMLElement, value: string): void {
92	    overlay.querySelectorAll<HTMLElement>(`.${BLOCK_OVERLAY.blockClass}`).forEach((el) => {
93	      el.style.transition = value;
94	    });
95	  }
96	
97	  private static resetBlocks(overlay: HTMLElement): void {
98	    overlay.querySelectorAll<HTMLElement>(`.${BLOCK_OVERLAY.blockClass}`).forEach((el) => {
99	      BlockOverlay._applyBlockBaseStyles(el);
100	    });
101	  }
102	
103	  private static staggerBlocks(
104	    overlay: HTMLElement,
105	    targetTransform: string,
106	    origin: "left" | "right",
107	  ): Promise<void> {
108	    return new Promise((resolve) => {
109	      const list = overlay.querySelectorAll<HTMLElement>(`.${BLOCK_OVERLAY.blockClass}`);
110	      list.forEach((el) => {
111	        el.style.transformOrigin = origin;
112	      });
113	      list.forEach((el, i) => {
114	        window.setTimeout(() => {
115	          el.style.transition = `transform ${BLOCK_OVERLAY_ANIM.durationMs}ms ${BLOCK_OVERLAY_ANIM.ease}`;
116	          el.style.transform = targetTransform;
117	        }, i * BLOCK_OVERLAY_ANIM.staggerMs);
118	      });
119	      window.setTimeout(resolve, list.length * BLOCK_OVERLAY_ANIM.staggerMs + BLOCK_OVERLAY_ANIM.durationMs);
120	    });
121	  }
122	
123	  private static prefersReducedMotion(): boolean {
124	    return ResponsiveRuntime.getDefault().getSnapshot().flags.reducedMotion;
125	  }
126	
127	  
128	  static playIn(): Promise<void> {
129	    const overlay = BlockOverlay.getOverlay();
130	    overlay.classList.add("is-active");
131	
132	    if (BlockOverlay.prefersReducedMotion()) {
133	      BlockOverlay.setBlocksTransform(overlay, "scaleX(1)", "left");
134	      return new Promise((r) => window.setTimeout(r, BLOCK_OVERLAY_ANIM.durationMs));
135	    }
136	
137	    BlockOverlay.setBlocksTransform(overlay, "scaleX(0)", "left");
138	    BlockOverlay.setBlocksTransition(overlay, "none");
139	    return new Promise<void>((resolve) => {
140	      FrameScheduler.request(() => {
141	        void overlay.offsetHeight;
142	        FrameScheduler.request(async () => {
143	          await BlockOverlay.staggerBlocks(overlay, "scaleX(1)", "left");
144	          resolve();
145	        });
146	      });
147	    });
148	  }
149	
150	  
151	  static async playOut(): Promise<void> {
152	    const overlay = BlockOverlay.getOverlay();
153	    if (!overlay.isConnected || !overlay.classList.contains("is-active")) return;
154	
155	    if (BlockOverlay.prefersReducedMotion()) {
156	      BlockOverlay.setBlocksTransform(overlay, "scaleX(0)", "right");
157	      overlay.classList.remove("is-active");
158	      BlockOverlay.resetBlocks(overlay);
159	      await new Promise((r) => window.setTimeout(r, BLOCK_OVERLAY_ANIM.durationMs));
160	      return;
