722	  private _detachChipWithGhost(node: HTMLElement, chip: HTMLElement): void {
723	    this._cancelChipLeave(chip);
724	
725	    const nodeRect = node.getBoundingClientRect();
726	    const chipRect = chip.getBoundingClientRect();
727	    const ghost = chip.cloneNode(true);
728	    if (!(ghost instanceof HTMLElement)) {
729	      chip.remove();
730	      return;
731	    }
732	
733	    ghost.classList.remove("is-entering");
734	    ghost.classList.add("is-leaving", "is-ghost");
735	    ghost.style.left = `${chipRect.left - nodeRect.left}px`;
736	    ghost.style.top = `${chipRect.top - nodeRect.top}px`;
737	    ghost.style.width = `${chipRect.width}px`;
738	    ghost.style.height = `${chipRect.height}px`;
739	
740	    node.append(ghost);
741	    chip.remove();
742	
743	    const timer = this._trackedTimeout(() => {
744	      this._chipLeaveTimers.delete(ghost);
745	      ghost.remove();
746	    }, CONTACT_WIZARD.chipLeaveMs);
747	
748	    this._chipLeaveTimers.set(ghost, timer);
749	  }
